local config = {
  ui_story_40180001_1_dialog_content = "Biarkan dia yang sepenuhnya menguasai kenyataan bicara lebih dulu—yaitu aku.",
  ui_story_40180001_2_dialog_content = "Tidak, sebagai bangsawan aristokrat Lumopolis, seharusnya aku yang mengurus ini.",
  ui_story_40180001_3_dialog_content = "Kalian ini bicara apa? Hal seperti ini seharusnya diurus oleh orang dewasa. Biar aku saja.",
  ui_story_40180001_4_dialog_content = "Tunggu, tunggu, tunggu...",
  ui_story_40180001_5_dialog_content = "Aku memang bilang ingin dengar dongeng sebelum tidur...",
  ui_story_40180001_6_dialog_content = "Tapi aku tidak mengira kalian akan sesemangat ini...",
  ui_story_40180001_7_dialog_content = "<size=36>Yang terpenting adalah kebenaran!</size>",
  ui_story_40180001_8_dialog_content = "<size=40>Percayalah pada bangsawan!</size>",
  ui_story_40180001_9_dialog_content = "<size=44>Ini tugas orang dewasa!</size>",
  ui_story_40180001_10_dialog_content = "(Bikin pusing saja... Tahu begini, aku takkan memanggil mereka bertiga.)",
  ui_story_40180001_11_dialog_content = "(Kisah yang sebelumnya mereka ceritakan itu sangat menarik, tapi sekarang mereka saling berebutan...)",
  ui_story_40180001_12_dialog_content = "Bicaralah, bocah polos. Katakan—siapa yang pantas menceritakan ceritanya terlebih dahulu.",
  ui_story_40180001_13_dialog_content = "Tentu saja yang punya cerita terbaik.",
  ui_story_40180001_14_dialog_content = "PlayerName ingin mendengarkan dongeng sebelum tidur. Kalau terlalu seru, dia malah akan kesulitan tidur.",
  ui_story_40180001_15_dialog_content = "Jadi, yang dongengnya paling membosankan sebaiknya diceritakan terakhir agar dia bisa tidur nyenyak.",
  ui_story_40180001_16_dialog_content = "Kalau begitu, mana mungkin aku menolak. Aku akan mulai...",
  ui_story_40180001_17_dialog_content = "Tunggu, kalau ceritanya dimulai dari yang paling menarik...",
  ui_story_40180001_18_dialog_content = "Berarti jelas aku yang mulai!",
  ui_story_40180001_19_dialog_content = "Aku pernah cerita soal penjarah makam yang fantastis. Kamu ingat, bocah polos?",
  ui_story_40180001_20_dialog_content = "Oh, itu... Aku...",
  ui_story_40180001_21_dialog_content = "Hei, aku juga sudah cerita tentang jiwa bangsawan dari moyangku kepada Navigator.",
  ui_story_40180001_22_dialog_content = "Kalian masih harus belajar dari yang lebih tua. Kebetulan... aku juga sudah menceritakan kisah berburu yang menarik kepada Navigator.",
  ui_story_40180001_23_dialog_content = "Ini sungguh dilema. Sebaiknya kita biarkan PlayerName memilih.",
  ui_story_40180001_24_dialog_content = "PlayerName, menurutmu, cerita mana yang sebelumnya paling menarik? Sebaiknya dia yang bercerita pertama malam ini. Bagaimana menurutmu?",
  ui_story_40180001_25_dialog_content = "A-aku...",
  ui_story_40180001_26_dialog_content = "Sebenarnya aku sudah lupa sebagian besar cerita kalian...",
  ui_story_40180001_27_dialog_content = "Menyedihkan sekali! Kamu lupa?!",
  ui_story_40180001_28_dialog_content = "Jangan marah, dong... Bagaimana kalau kalian ingatkan lagi ceritanya?",
  ui_story_40180001_29_dialog_content = "Hmm, tiga cerita waktu itu...",
  ui_story_40180001_30_option_content = "Cerita Sikare Dantes itu apa?",
  ui_story_40180001_31_dialog_content = "Hei, bocah polos, kamu benar-benar sudah lupa? Aku menangkap seorang penjarah makam dan memintanya untuk menceritakan kisahnya selama sepuluh hari dan sepuluh malam.",
  ui_story_40180001_32_dialog_content = "Salah satu ceritanya adalah bagaimana dia tersesat di Northland Forest. Dia bertemu anak aneh yang membimbingnya keluar dari hutan.",
  ui_story_40180001_33_dialog_content = "Aku sangat menyukai cerita ini, jadi sebagai gantinya, aku memberikan penjarah makam itu hartaku yang paling berharga.",
  ui_story_40180001_34_dialog_content = "Itu juga sungguhan.",
  ui_story_40180001_35_dialog_content = "Cerita mengenai harta... Benar juga.",
  ui_story_40180001_36_option_content = "Lalu cerita Beverly?",
  ui_story_40180001_37_dialog_content = "Apa kamu ingat, PlayerName? Kamu bertanya padaku tentang jiwa seorang bangsawan.",
  ui_story_40180001_38_dialog_content = "Aku menceritakan kisah ekspedisi nenek moyangku ke Northland.",
  ui_story_40180001_39_dialog_content = "Mereka mengalahkan Eclipsite di sana dan menolong penduduk desa. Meski memakan banyak korban, mereka tetap memenuhi tugas sebagai bangsawan.",
  ui_story_40180001_40_dialog_content = "Namun, mereka tidak menerima makanan dan minuman yang diberikan penduduk desa. Di sini, pendapat kita berdua berbeda.",
  ui_story_40180001_41_dialog_content = "Oh, ya, rasanya aku mulai ingat cerita itu.",
  ui_story_40180001_42_option_content = "Lalu cerita Constantine?",
  ui_story_40180001_43_dialog_content = "Nak, aku bercerita tentang kisah berburu Eclipsite. Kamu ingat?",
  ui_story_40180001_44_dialog_content = "Saat berburu di Northland Forest, aku bertemu dengan makhluk aneh.",
  ui_story_40180001_45_dialog_content = "Aku mengira itu seekor Eclipsite, tapi setelah mengejarnya selama tiga jam, ternyata itu adalah seorang <color=#FFB400>anak kecil</color>.",
  ui_story_40180001_46_dialog_content = "Anak itu berpakaian tipis, dan tidak mau pulang, jadi aku memberikan <color=#FFB400>mantelku</color> kepada anak itu.",
  ui_story_40180001_47_dialog_content = "Kemudian aku <color=#FFB400>menemani anak itu keluar dari hutan</color> dan hendak mengantarnya pulang, tapi anak itu melarikan diri.",
  ui_story_40180001_48_dialog_content = "Dia bahkan tidak membawa mantelku! Aku sangat khawatir, dia pasti akan masuk angin!",
  ui_story_40180001_49_dialog_content = "Cerita yang ini... agak aneh.",
  ui_story_40180001_50_dialog_content = "Baiklah, aku ingat ketiga cerita itu sekarang.",
  ui_story_40180001_51_dialog_content = "Semuanya sangat menarik... tapi tidak cocok untuk jadi dongeng sebelum tidur.",
  ui_story_40180001_52_dialog_content = "Untuk sekarang... rasanya sulit sekali memilih siapa yang harus bercerita lebih dulu.",
  ui_story_40180001_53_dialog_content = "Tapi kalau harus memilih, aku...",
  ui_story_40180001_54_dialog_content = "Tunggu dulu!",
  ui_story_40180001_55_dialog_content = "Eh?",
  ui_story_40180001_56_dialog_content = "Tunggu, PlayerName... Memilihnya nanti saja.",
  ui_story_40180001_57_dialog_content = "Aku baru saja menyadari hal yang mengerikan...",
  ui_story_40180001_58_dialog_content = "Hah... Apa—?!",
  ui_story_40180001_59_dialog_content = "Sikare dan Constantine sama-sama bercerita tentang... <color=#FFB400>seorang anak di Northland</color>...",
  ui_story_40180001_60_dialog_content = "Hah? Ya, benar...",
  ui_story_40180001_61_dialog_content = "Constantine dan penjarah makam yang Sikare ceritakan bertemu seorang anak di Northland Forest, lalu...",
  ui_story_40180001_X61_dialog_content = "<color=#FFB400>Mereka berjalan keluar dari hutan bersama anak itu</color>.",
  ui_story_40180001_62_dialog_content = "Benar?",
  ui_story_40180001_63_dialog_content = "Ya.",
  ui_story_40180001_64_dialog_content = "Ya, lalu anak itu meninggalkan mantelku...",
  ui_story_40180001_65_dialog_content = "Mantelnya tidak penting... Sebenarnya aku juga mendengar cerita yang sama <color=#FFB400>di desa tempat nenek moyangku melakukan ekspedisi</color>!",
  ui_story_40180001_66_dialog_content = "Apa?!",
  ui_story_40180001_67_dialog_content = "Apa? Kamu bertemu anak itu juga? Apa anak itu masuk angin...?",
  ui_story_40180001_68_dialog_content = "Soal masuk angin atau tidaknya itu juga tidak penting!",
  ui_story_40180001_69_dialog_content = "Beberapa waktu lalu, aku pergi ke Northland—ke desa tempat nenek moyangku berkunjung.",
  ui_story_40180001_70_dialog_content = "Aku pergi mengunjungi keturunan penduduk desa itu, dan sebagai wakil moyangku, menerima hadiah makanan dan minuman mereka.",
  ui_story_40180001_71_dialog_content = "Kami mengobrol dengan riang, lalu mereka menceritakan kisah-kisah aneh di Northland, termasuk...",
  ui_story_40180001_X71_dialog_content = "<color=#FFB400>Kisah tentang anak aneh di Northland Forest</color>.",
  ui_story_40180001_72_dialog_content = "Apa? Baru-baru ini? Anak itu masih pergi bermain ke hutan itu? Nakal sekali dia...",
  ui_story_40180001_73_dialog_content = "Setelah itu bagaimana?! Aku ingin tahu kelanjutannya!",
  ui_story_40180001_74_dialog_content = "Beverly, penduduk desa di Northland itu bilang apa?",
  ui_story_40180001_75_dialog_content = "Mereka bilang, bulan lalu, seorang penduduk desa tersesat di <color=#FFB400>Northland Forest</color> dan tak tahu jalan keluar.",
  ui_story_40180001_76_dialog_content = "Dia pergi ke berbagai arah, dan dia terus dikelilingi pepohonan.",
  ui_story_40180001_77_dialog_content = "Dia terus berjalan hingga begitu gelap sampai tidak bisa melihat jalan dengan jelas.",
  ui_story_40180001_A1_dialog_content = "Lalu sang penduduk desa itu terduduk di tanah dengan putus asa, dan dia yakin akan mati sendirian di hutan ini.",
  ui_story_40180001_78_dialog_content = "Sebenarnya... Aku dengar dia bahkan mulai menangis. Dia pria yang tangguh, tapi tetap saja rakyat awam.",
  ui_story_40180001_79_dialog_content = "Lalu?! Apa yang terjadi padanya?",
  ui_story_40180001_80_dialog_content = "Lalu... saat menangis, dia memikirkan anaknya yang menunggu di rumah.",
  ui_story_40180001_81_dialog_content = "Istrinya sudah meninggal, dan anaknya tinggal sendirian. Dia berpikir jika tak bisa keluar dari hutan, anaknya tak hanya kehilangan ibunya, tapi juga ayahnya...",
  ui_story_40180001_A2_dialog_content = "Dia mulai putus asa, dan mulai meneriakkan nama anaknya.",
  ui_story_40180001_82_dialog_content = "Tapi di luar dugaan, saat dia berteriak... anaknya membalas panggilannya!",
  ui_story_40180001_83_dialog_content = "Apa?!",
  ui_story_40180001_84_dialog_content = "Dia terkejut, menoleh ke belakang, dan melihat <color=#FFB400>anaknya</color> muncul dari tengah hutan lebat.",
  ui_story_40180001_85_dialog_content = "Lalu... anak itu mengenakan <color=#FFB400>mantel aneh</color>, sama persis dengan yang Constantine kenakan sekarang.",
  ui_story_40180001_86_dialog_content = "Apa?!",
  ui_story_40180001_87_dialog_content = "Anak itu membuang mantelku, lalu membuatnya lagi yang persis sama?!",
  ui_story_40180001_88_dialog_content = "Ah... dia pasti mengembalikannya padaku karena mengira aku akan kedinginan.",
  ui_story_40180001_89_dialog_content = "Seharusnya... Seharusnya aku berikan sesuatu yang lebih cocok untuk anak itu... Kenapa aku tidak sadar... Aku akan buat sekarang juga!",
  ui_story_40180001_90_dialog_content = "Anak itu... Beverly, tolong lanjutkan! Soal <color=#FFB400>anak itu</color>, dan penduduk desa tersebut!",
  ui_story_40180001_91_dialog_content = "Penduduk desa itu... Tentu saja, dia terkejut.",
  ui_story_40180001_92_dialog_content = "Dia meneriakkan nama anaknya dan berlari untuk memeluknya.",
  ui_story_40180001_93_dialog_content = "Air matanya menetes tak terkendali, melelehkan salju di tanah hutan itu.",
  ui_story_40180001_94_dialog_content = "Anak itu memeluknya dengan bahagia, berteriak-teriak \"Ayah!\" dengan semangat dan berkata, \"Aku ingin pulang bersama Ayah.\"",
  ui_story_40180001_95_dialog_content = "Sang penduduk desa begitu senang hingga dia tidak bisa menjawab. Dia terus mengangguk, lalu berdiri selagi anak itu memeluknya.",
  ui_story_40180001_96_dialog_content = "Lalu, mereka bergandengan tangan dan berjalan maju, langkah demi langkah.",
  ui_story_40180001_97_dialog_content = "Tak lama kemudian, <color=#FFB400>mereka berhasil keluar dari hutan</color>.",
  ui_story_40180001_98_dialog_content = "Setelah keluar dari hutan, penduduk desa ini tahu jalan kembali ke desa. Dia begitu senang, dan hendak menggendong anaknya dengan bahagia.",
  ui_story_40180001_99_dialog_content = "Namun, begitu dia menengok, dia tiba-tiba menemukan...",
  ui_story_40180001_100_dialog_content = "<anim type=Shake><color=#FFB400>Tak ada seorang pun di sampingnya. Dia hanya dikelilingi oleh salju putih...</color></anim> Benar?",
  ui_story_40180001_101_dialog_content = "Benar! Kok kamu tahu?",
  ui_story_40180001_102_dialog_content = "Karena penjarah makam itu mengatakan hal yang sama.",
  ui_story_40180001_103_dialog_content = "Dia dituntun keluar hutan oleh seorang anak yang aneh, lalu saat dia menoleh untuk berterima kasih, tidak ada siapa pun di sana.",
  ui_story_40180001_104_dialog_content = "<anim type=Shake><color=#FFB400>Dia bahkan tidak bisa menemukan jejak kaki anak itu</color></anim>.",
  ui_story_40180001_105_dialog_content = "Sudah kuduga! Ada banyak orang yang pernah bertemu anak itu!",
  ui_story_40180001_106_dialog_content = "Tampaknya begitu.",
  ui_story_40180001_107_dialog_content = "Tunggu... Apa mungkin ini halusinasi massal?",
  ui_story_40180001_108_dialog_content = "Hutan itu sangat dingin—mungkin saja orang yang pingsan di sana setelah tersasar melihat ilusi seperti itu.",
  ui_story_40180001_109_dialog_content = "Kata-katamu mungkin saja benar, bocah polos, tapi...",
  ui_story_40180001_110_dialog_content = "Constantine <color=#FFB400>bertemu langsung</color> dengan anak tersebut.",
  ui_story_40180001_111_dialog_content = "Tidak salah lagi... Anak nakal itu...",
  ui_story_40180001_112_dialog_content = "Aku sempat ragu apakah anak itu benar-benar ada...",
  ui_story_40180001_A3_dialog_content = "Si penjarah makam dan penduduk desa yang kamu temui tidak mengarangnya... Itu juga bukan halusinasi yang Constantine alami setelah membunuh terlalu banyak Eclipsite...",
  ui_story_40180001_113_dialog_content = "Hei! Mana mungkin itu halusinasi?! Aku memberikan mantelku dan memakaikannya pada anak itu! Aku menyentuh langsung anak itu!",
  ui_story_40180001_114_dialog_content = "Baiklah... Tapi masih ada yang kuragukan.",
  ui_story_40180001_115_dialog_content = "Beverly, kamu bilang anak di cerita itu adalah anak penduduk desa tersebut...",
  ui_story_40180001_116_dialog_content = "Oh... Ya, benar.",
  ui_story_40180001_117_dialog_content = "Bagian itu cukup mudah dimengerti. Tidak aneh bagi seseorang untuk salah mengira seorang anak kecil sebagai anak sendiri di tengah tekanan batin seberat itu.",
  ui_story_40180001_118_dialog_content = "Kalau dipikir begitu, masuk akal, sih...",
  ui_story_40180001_119_dialog_content = "Tapi ini masih sangat aneh!",
  ui_story_40180001_120_dialog_content = "Kalau aku ingat-ingat, Constantine mengatakan bahwa Northland Forest itu <color=#FFB400>sama sekali tidak ditinggali manusia</color>.",
  ui_story_40180001_121_dialog_content = "Mana mungkin anak kecil bisa di sana sendirian?",
  ui_story_40180001_122_dialog_content = "Benar, dan melihat kisah-kisah anak ini membantu orang lain, dan <color=#FFB400>menuntun mereka keluar</color> tiga kali...",
  ui_story_40180001_123_dialog_content = "Tiga kali? Bukankah cuma dua kali—si penjarah makam dan penduduk desa itu?",
  ui_story_40180001_124_dialog_content = "Kalau aku, aku yang menuntun anak itu pulang.",
  ui_story_40180001_125_dialog_content = "Mau berapa kali juga... Anak ini pasti sangat mengenal jalan di hutan itu.",
  ui_story_40180001_126_dialog_content = "Lebih kenal dibanding penjarah makam maupun penduduk desa sekalipun.",
  ui_story_40180001_127_dialog_content = "Ya, penjarah makam yang kutemui <color=#FFB400>bahkan meninggalkan penanda saat berjalan di sana</color>. Dia jelas sangat berpengalaman.",
  ui_story_40180001_128_dialog_content = "Tapi pada akhirnya dia tetap tersesat.",
  ui_story_40180001_129_dialog_content = "Penduduk desa itu juga <color=#FFB400>mencoba berjalan ke berbagai arah</color>, tapi tidak bisa menemukan jalan keluar.",
  ui_story_40180001_130_dialog_content = "Jadi... Agak membingungkan bila anak aneh itu sangat familier dengan jalan di hutan...",
  ui_story_40180001_131_dialog_content = "Ini lebih seperti...",
  ui_story_40180001_132_option_content = "Anak itu muncul entah dari mana dan menolong orang-orang yang tersesat?",
  ui_story_40180001_133_dialog_content = "Hei, aku melihat baik-baik anak itu... dan dia jelas tidak punya sayap!",
  ui_story_40180001_134_option_content = "Mungkin anak itu menggali lubang keluar hutan?",
  ui_story_40180001_135_dialog_content = "Hei, aku melihat baik-baik anak itu... dan dia jelas tidak punya sekop!",
  ui_story_40180001_136_dialog_content = "Aneh... Ini sangat aneh...",
  ui_story_40180001_137_dialog_content = "Ya, menurutku ini sangat aneh.",
  ui_story_40180001_138_dialog_content = "Saat jalan keluar tidak bisa ditemukan, <color=#FFB400>anak ini menuntun orang-orang tersesat keluar dari hutan</color>...",
  ui_story_40180001_139_dialog_content = "Lalu saat si penduduk desa melihat anak itu, dia <color=#FFB400>memakai mantel aneh milik Constantine</color>...",
  ui_story_40180001_140_dialog_content = "Mana mungkin seorang anak bisa membuat replika sempurna dari barang unik seperti itu di tengah hutan kosong?",
  ui_story_40180001_141_dialog_content = "Benar... Seorang anak kecil pasti kesulitan untuk bisa membuat mantel seperti ini...",
  ui_story_40180001_142_dialog_content = "Bahkan jarinya bisa tertusuk jarum saat menjahit kancingnya...",
  ui_story_40180001_143_dialog_content = "<size=42>Sudah kubilang bukan itu masalahnya!</size>",
  ui_story_40180001_144_dialog_content = "Bahan dan modelnya... <color=#FFB400>Bagaimana seorang anak bisa membuat baju seperti itu</color>? Terlebih lagi sama persis dengan punya Constantine! Itu masalahnya!",
  ui_story_40180001_145_dialog_content = "Jadi, jelas ada yang salah dengan anak itu... Tidak! <color=#FFB400>Anak itulah masalah utama dari semua ini</color>!",
  ui_story_40180001_146_dialog_content = "Ah... Beverly, ayo coba pertahankan keeleganan bangsawanmu itu!",
  ui_story_40180001_147_dialog_content = "Jangan sampai terpengaruh cara pikir om-om tidak jelas ini.",
  ui_story_40180001_148_dialog_content = "Ehem. Maaf, aku kehilangan kendali.",
  ui_story_40180001_149_dialog_content = "Sebenarnya, sebagai orang yang <color=#FFB400>berkontak langsung</color> dengan anak itu, aku ingin bertanya sesuatu padanya...",
  ui_story_40180001_150_dialog_content = "Kamu ingin tanya apa? Sepertinya anak itu cukup terampil, jadi aku rasa tidak aneh kalau dia bisa membuat baju...",
  ui_story_40180001_151_dialog_content = "Ya, tidak ada gunanya bertanya padamu.",
  ui_story_40180001_152_dialog_content = "Bagaimana kalau bertanya pada orang lain? Jika mereka berasal dari Northland, mungkin pernah dengar tentang dia...",
  ui_story_40180001_153_dialog_content = "Hei, bocah polos, apa kamu kenal seseorang dari Northland?",
  ui_story_40180001_154_dialog_content = "Apa mereka pernah dengar legenda aneh seperti ini?",
  ui_story_40180001_155_dialog_content = "Coba kuingat...",
  ui_story_40180001_156_option_content = "Queen Bethlehem?",
  ui_story_40180001_157_dialog_content = "Aku rasa dia pasti tahu mengenai hal ini, tapi kemungkinan dia tak punya waktu untuk mendengarkan kita.",
  ui_story_40180001_158_option_content = "Bagaimana kalau Constantine?",
  ui_story_40180001_159_dialog_content = "Kamu masih belum paham juga, bocah polos? Kita takkan bisa berkomunikasi dengan om-om aneh yang terus terpaku dengan mantel ini!",
  ui_story_40180001_160_dialog_content = "Oh... Yah...",
  ui_story_40180001_161_dialog_content = "Bagaimana dengan Louise?",
  ui_story_40180001_162_dialog_content = "Kalian mungkin menganggap pemikiranku aneh... Tapi aku juga penasaran bagaimana nasib anak itu.",
  ui_story_40180001_163_dialog_content = "Louise suka mempelajari berbagai legenda. Seharusnya dia tahu.",
  ui_story_40180001_164_dialog_content = "Baiklah, akan kucari dia.",
  ui_story_40180001_165_dialog_content = "Aku mengerti.",
  ui_story_40180001_166_dialog_content = [[
Penjarah makam yang Sikare temui, penduduk desa yang Beverly dengar kisahnya, bahkan Constantine sendiri, semuanya mengalami hal aneh di Northland Forest...
Fenomena yang menarik...]],
  ui_story_40180001_167_dialog_content = "Si penjarah makam dan penduduk desa tersesat di hutan itu. Mereka kira takkan bisa keluar, tapi kemudian dibawa keluar oleh seorang anak yang muncul tiba-tiba.",
  ui_story_40180001_168_dialog_content = "Di sisi lain, Constantine ingin mengantar anak aneh itu pulang. Tapi kemungkinan dia sebenarnya juga tersesat dan tidak menyadarinya...",
  ui_story_40180001_169_dialog_content = "Jadi, sekarang semua orang ingin tahu <color=#FFB400>siapa anak ini</color>, benar?",
  ui_story_40180001_170_dialog_content = "Benar!",
  ui_story_40180001_171_dialog_content = "Aku meminta mereka bertiga menceritakan dongeng sebelum tidur... karena aku sedang susah tidur.",
  ui_story_40180001_172_dialog_content = "Gara-gara ini, aku malah jadi makin tidak bisa tidur lagi!",
  ui_story_40180001_173_dialog_content = "Kalau kebenaran tentang anak ini masih belum terungkap... Bisa-bisa aku tidak tidur sampai pagi!",
  ui_story_40180001_174_dialog_content = "Begitu, ya.",
  ui_story_40180001_175_dialog_content = "Sayang sekali... Sepertinya kamu memang tidak akan tidur sampai pagi.",
  ui_story_40180001_176_dialog_content = "Apa? M-maksudmu...",
  ui_story_40180001_177_dialog_content = "Anak ini... Dia memang muncul <color=#FFB400>di legenda-legenda Northland</color>.",
  ui_story_40180001_178_dialog_content = "Ada banyak orang yang tersesat di dalam Northland Forest.",
  ui_story_40180001_179_dialog_content = "Baik pengelana dengan kompas dan peta, pemburu Eclipsite ahli, maupun Queen Bethlehem yang agung sekalipun...",
  ui_story_40180001_180_dialog_content = "Begitu masuk ke hutan itu, semuanya takkan bisa keluar.",
  ui_story_40180001_181_dialog_content = "Itu karena jalan di hutan itu terus berubah, seakan-akan hidup.",
  ui_story_40180001_182_dialog_content = "Berubah?",
  ui_story_40180001_183_dialog_content = "Ya. Tiap menit, tiap detik, tiap saat—semua jalannya berubah.",
  ui_story_40180001_184_dialog_content = "Semua yang masuk ke hutan itu akan tersesat, kehilangan arah, lalu putus asa.",
  ui_story_40180001_185_dialog_content = "Mengerikan sekali!",
  ui_story_40180001_186_dialog_content = "Untungnya, ada seorang anak baik yang tinggal di hutan itu. Tidak ada yang tahu dari mana asalnya...",
  ui_story_40180001_187_dialog_content = "Seorang anak yang baik, penuh semangat, dan sangat ramah.",
  ui_story_40180001_188_dialog_content = "Ketika seorang pengelana menjadi putus asa, anak itu akan muncul dan jalannya akan berhenti berubah.",
  ui_story_40180001_189_dialog_content = "Anak itu menggandeng pengelana yang tersesat tersebut dan menuntun mereka keluar dari hutan.",
  ui_story_40180001_190_dialog_content = "Sang anak menuntun mereka ke dataran bersaju, Lake Mirror, dan kembali ke arah rumah mereka.",
  ui_story_40180001_191_dialog_content = "Itulah legenda yang kuketahui. Namanya <color=#FFB400>Sang Anak dari Hutan Sesat</color>.",
  ui_story_40180001_192_dialog_content = "Sekian.",
  ui_story_40180001_193_dialog_content = "Sudah? Begitu saja?",
  ui_story_40180001_194_dialog_content = "Ya. Jadi, PlayerName, kamu ingin tahu tentang siapa anak itu dan ada apa sebenarnya dengan hutan itu...",
  ui_story_40180001_195_dialog_content = "Atau mungkin juga pertanyaan-pertanyaan baru setelah mendengar legendanya, PlayerName, misalnya...",
  ui_story_40180001_A4_dialog_content = "Apakah jalan hutan itu benar-benar selalu berubah? Mengapa jalannya berhenti berubah saat anak itu muncul?",
  ui_story_40180001_196_dialog_content = "Sayangnya, <color=#FFB400>aku tidak punya jawabannya</color>.",
  ui_story_40180001_197_dialog_content = "Namanya juga legenda—cara kerja ceritanya tidak harus dijelaskan.",
  ui_story_40180001_198_dialog_content = "Benar juga... dan ini cukup pantas untuk dipikirkan.",
  ui_story_40180001_199_dialog_content = "Sepertinya ada kebenaran di dalamnya...",
  ui_story_40180001_200_dialog_content = "Aku juga merasakan... semacam kisah peringatan.",
  ui_story_40180001_201_dialog_content = "Sebagai seorang bangsawan, kita harus lebih teliti... Sebisa mungkin.",
  ui_story_40180001_202_dialog_content = "Hei! Kenapa kalian percaya dengan ceritanya begitu saja?!",
  ui_story_40180001_203_dialog_content = "Aku malah makin bingung sekarang... dan tidak mungkin aku bisa tidur!",
  ui_story_40180001_204_dialog_content = "Constantine! Kamu juga merasa aneh, 'kan?! Tempat seaneh itu seharusnya dicari tahu kebenarannya seakurat mungkin, 'kan?!",
  ui_story_40180001_205_dialog_content = "Ya! Ini sangat aneh!",
  ui_story_40180001_206_dialog_content = "Ya, 'kan?!",
  ui_story_40180001_207_dialog_content = "Kalau jalan di hutan itu selalu berubah, <color=#FFB400>kenapa aku tidak menyadarinya</color>?",
  ui_story_40180001_208_dialog_content = "Ya!",
  ui_story_40180001_209_dialog_content = "Lalu, kalau anak ini tinggal di hutan, berarti rumahnya ada di hutan itu.",
  ui_story_40180001_A5_dialog_content = "Tapi kalau jalannya selalu berubah, bagaimana caranya dia pulang?",
  ui_story_40180001_210_dialog_content = "Oh... Ya!",
  ui_story_40180001_211_dialog_content = "Kalau anak itu tidak bisa pulang, bagaimana caranya dia bisa membuat mantel persis punyaku?",
  ui_story_40180001_212_dialog_content = "Eh... Ya!",
  ui_story_40180001_213_dialog_content = "Tidak, tidak... Pasti mantel yang dilihat penduduk desa itu hanya ilusi. Anak itu pasti masih kedinginan!",
  ui_story_40180001_214_dialog_content = "Hah?",
  ui_story_40180001_215_dialog_content = "Aku harus bergegas... Aku harus ke Northland dan memberikan pakaian untuk anak itu!",
  ui_story_40180001_X215_dialog_content = "Kalau tetap seperti itu, dia pasti akan sakit!",
  ui_story_40180001_216_dialog_content = "<size=36>Kau memang tidak mengerti ini ya...</size>"
}
return config
